import react from '@vitejs/plugin-react'
import { defineConfig } from 'vitest/config'

// The repo root is published by GitHub Pages' legacy branch deployment, so the
// root `index.html` is generated by `scripts/publish-pages.mjs`. The Vite source
// entry is `dev.html`; `pnpm dev` opens it for you.
//
// `base: './'` keeps asset URLs relative, so the site works both from
// https://<user>.github.io/<repo>/ and from a user/organisation page.
export default defineConfig({
  base: './',
  plugins: [react()],
  server: {
    open: '/dev.html',
  },
  build: {
    outDir: 'dist',
    sourcemap: false,
    rollupOptions: {
      input: 'dev.html',
    },
  },
  test: {
    environment: 'node',
    include: ['tests/**/*.test.ts'],
  },
})
